 static Dictionary<string,object> WholeJobCost(IntPtr process,long creation,IntPtr job,string exe,Dictionary<string,object> observation){var members=PinMembers(job,process,creation,exe,observation);try{var evidence=new List<object>();var ids=new uint[members.Count];for(int i=0;i<members.Count;i++){var m=members[i];ids[i]=m.pid;evidence.Add(new{pid=m.pid,creation=m.creation,image=m.image,parent_pid=m.parent,role=m.pid==GetProcessId(process)?"original app":"same-image direct child; role not established"});}Array.Sort(ids);Accounting before=new Accounting(),after=new Accounting();Require(QueryInformationJobObject(job,1,out before,(uint)Marshal.SizeOf(typeof(Accounting)),IntPtr.Zero),"Job CPU baseline");var clock=System.Diagnostics.Stopwatch.StartNew();ulong wsPeak=0,privatePeak=0;int samples=0;long ak0,au0,ak1,au1,actual,exit;Require(GetProcessTimes(process,out actual,out exit,out ak0,out au0)&&actual==creation,"App CPU baseline");while(true){Require(SameMembers(ids,Members(job)),"Idle Job member set changed");ulong ws=0,priv=0;foreach(var m in members){long c,k,u;Require(GetProcessTimes(m.handle,out c,out exit,out k,out u)&&c==m.creation&&WaitForSingleObject(m.handle,0)==258,"Pinned member lifetime changed");Memory memory;Require(GetProcessMemoryInfo(m.handle,out memory,(uint)Marshal.SizeOf(typeof(Memory))),"Pinned member memory");ws=checked(ws+Number(memory.workingSet));priv=checked(priv+Number(memory.privateUsage));}wsPeak=Math.Max(wsPeak,ws);privatePeak=Math.Max(privatePeak,priv);Require(++samples<=128,"Job sample bound");if(clock.Elapsed.TotalSeconds>=10)break;Thread.Sleep(100);}double elapsed=clock.Elapsed.TotalSeconds;Require(elapsed>=10&&elapsed<12&&QueryInformationJobObject(job,1,out after,(uint)Marshal.SizeOf(typeof(Accounting)),IntPtr.Zero)&&after.kernel>=before.kernel&&after.user>=before.user,"Job CPU terminal sample");Require(GetProcessTimes(process,out actual,out exit,out ak1,out au1)&&actual==creation,"App CPU terminal");double jobCpu=(after.kernel-befor