public static class Program {
 public static string FileHash(string path){using(var f=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read))using(var sha=System.Security.Cryptography.SHA256.Create()){if(f.Length>268435456)throw new Exception("Hash size bound");return BitConverter.ToString(sha.ComputeHash(f)).Replace("-","").ToLowerInvariant();}}
 static string Full(string path){if(!Path.IsPathRooted(path)||path.Length>=248)throw new Exception("Bounded absolute plain Windows path required");string full=Path.GetFullPath(path);string p=full;while(p!=null){if(File.Exists(p)||Directory.Exists(p)){if((File.GetAttributes(p)&FileAttributes.ReparsePoint)!=0)throw new Exception("Original path reparse rejected");}p=Path.GetDirectoryName(p);}return full;}
 static void Require(bool condition,string message){if(!condition)throw new Exception(message);}
 [StructLayout(LayoutKind.Sequential)] struct IdleSA {public int length;public IntPtr descriptor;public int inherit;}
 [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)] static extern bool CreateDirectoryW(string path,ref IdleSA attributes);
 static void PrivatePlain(string path){
  Require(Path.IsPathRooted(path)&&Path.GetFullPath(path)==path,"Absolute normalized fixture path required");
  string current=path;int count=0;
  while(!String.IsNullOrEmpty(current)){
   Require(++count<=512,"Path ancestor bound");
   if(File.Exists(current)||Directory.Exists(current))Require((File.GetAttributes(current)&FileAttributes.ReparsePoint)==0,"Reparse fixture path rejected");
   string next=Path.GetDirectoryName(current);if(next==current)break;current=next;
  }
 }
 static void PrivateDirectory(string path){
  PrivatePlain(path);Require(!File.Exists(path)&&!Directory.Exists(path),"Fresh private directory required");
  var sid=System.Security.Principal.WindowsIdentity.GetCurrent().User;Require(sid!=null,"Current SID unavailable");
  var security=new System.Security.AccessControl.DirectorySecurity();security.SetOwner(sid);security.SetAccessRuleProtection(true,false);
  security.AddAccessRule(new System.Security.AccessControl.FileSystemAccessRule(sid,System.Security.AccessControl.FileSystemRights.FullControl,
   System.Security.AccessControl.InheritanceFlags.ContainerInherit|System.Security.AccessControl.InheritanceFlags.ObjectInherit,
   System.Security.AccessControl.PropagationFlags.None,System.Security.AccessControl.AccessControlType.Allow));
  byte[] bytes=security.GetSecurityDescriptorBinaryForm();GCHandle pinned=GCHandle.Alloc(bytes,GCHandleType.Pinned);
  try{IdleSA sa=new IdleSA();sa.length=Marshal.SizeOf(typeof(IdleSA));sa.descriptor=pinned.AddrOfPinnedObject();
   bool created=CreateDirectoryW(path,ref sa);int error=created?0:Marshal.GetLastWin32Error();Require(created,"Create-only private directory failed, native error "+error);
  }finally{pinned.Free();}
  PrivatePlain(path);var observed=new DirectoryInfo(path).GetAccessControl();Require(observed.AreAccessRulesProtected,"Private ACL not protected");
  Require(observed.GetOwner(typeof(System.Security.Principal.SecurityIdentifier)).Equals(sid),"Private owner mismatch");
